use std::collections::HashSet;
use std::path::{Component, Path, PathBuf};

use super::{GeneratedRustDevice, RustBackendError};

const GENERATED_DEVICE_MARKER_FILE: &str = ".rspice-veriloga-generated";
const GENERATED_DEVICE_MARKER_CONTENTS: &str =
    "Generated by the RSpice Verilog-A Rust backend. Safe to remove when stale.\n";

pub fn write_text_file_if_changed(
    path: impl AsRef<Path>,
    contents: &str,
) -> Result<bool, RustBackendError> {
    write_text_file_if_changed_for_module(path.as_ref(), contents, "<generated>")
}

pub fn cleanup_stale_generated_device_folders<I, S>(
    root: impl AsRef<Path>,
    expected_folders: I,
) -> Result<(), RustBackendError>
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let root = root.as_ref();
    let mut expected = HashSet::new();
    let mut case_folded = HashSet::new();
    for folder in expected_folders {
        let folder = folder.as_ref();
        validate_device_folder_name(folder, "<generated>")?;
        if !expected.insert(folder.to_string()) {
            return Err(duplicate_device_folder_error(folder));
        }
        if !case_folded.insert(folder.to_ascii_lowercase()) {
            return Err(case_colliding_device_folder_error(folder));
        }
    }

    std::fs::create_dir_all(root).map_err(|error| {
        RustBackendError::internal(
            "<generated>",
            "<devices>",
            format!(
                "failed to create generated devices directory '{}': {error}",
                root.display()
            ),
        )
    })?;

    for entry in std::fs::read_dir(root).map_err(|error| {
        RustBackendError::internal(
            "<generated>",
            "<devices>",
            format!(
                "failed to inspect generated devices directory '{}': {error}",
                root.display()
            ),
        )
    })? {
        let entry = entry.map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                "<devices>",
                format!(
                    "failed to inspect generated devices directory '{}': {error}",
                    root.display()
                ),
            )
        })?;
        let path = entry.path();
        let file_type = entry.file_type().map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                "<devices>",
                format!(
                    "failed to inspect generated device folder '{}': {error}",
                    path.display()
                ),
            )
        })?;
        if !file_type.is_dir() {
            continue;
        }

        let folder = entry.file_name().to_string_lossy().into_owned();
        if expected.contains(&folder) {
            continue;
        }
        if !path.join(GENERATED_DEVICE_MARKER_FILE).is_file() {
            continue;
        }

        std::fs::remove_dir_all(&path).map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                "<devices>",
                format!(
                    "failed to remove stale generated device folder '{}': {error}",
                    path.display()
                ),
            )
        })?;
    }

    Ok(())
}

pub fn write_generated_device(
    root: impl AsRef<Path>,
    device: &GeneratedRustDevice,
) -> Result<Vec<PathBuf>, RustBackendError> {
    let root = root.as_ref();
    validate_device_folder_name(&device.folder_name, &device.module_name)?;
    let mut expected_files = HashSet::with_capacity(device.files.len());
    let mut case_folded_files = HashSet::with_capacity(device.files.len());
    for file in &device.files {
        validate_relative_path(&file.relative_path, &device.module_name)?;
        let relative_path = Path::new(&file.relative_path).to_path_buf();
        if !expected_files.insert(relative_path) {
            return Err(duplicate_relative_path_error(
                &device.module_name,
                &file.relative_path,
            ));
        }
        let case_folded_path = case_folded_relative_path(Path::new(&file.relative_path));
        if !case_folded_files.insert(case_folded_path) {
            return Err(case_colliding_relative_path_error(
                &device.module_name,
                &file.relative_path,
            ));
        }
    }

    let device_dir = root.join(&device.folder_name);
    std::fs::create_dir_all(&device_dir).map_err(|error| {
        RustBackendError::internal(
            "<generated>",
            &device.module_name,
            format!(
                "failed to create generated device directory '{}': {error}",
                device_dir.display()
            ),
        )
    })?;

    write_text_file_if_changed_for_module(
        &device_dir.join(GENERATED_DEVICE_MARKER_FILE),
        GENERATED_DEVICE_MARKER_CONTENTS,
        &device.module_name,
    )?;

    cleanup_stale_generated_rust_files(&device_dir, &expected_files, &device.module_name)?;

    let mut written = Vec::with_capacity(device.files.len());
    for file in &device.files {
        let path = device_dir.join(&file.relative_path);
        write_text_file_if_changed_for_module(&path, &file.contents, &device.module_name)?;
        written.push(path);
    }

    Ok(written)
}

fn write_text_file_if_changed_for_module(
    path: &Path,
    contents: &str,
    module_name: &str,
) -> Result<bool, RustBackendError> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                module_name,
                format!(
                    "failed to create generated file parent '{}': {error}",
                    parent.display()
                ),
            )
        })?;
    }
    if std::fs::read_to_string(path).ok().as_deref() == Some(contents) {
        return Ok(false);
    }

    std::fs::write(path, contents).map_err(|error| {
        RustBackendError::internal(
            "<generated>",
            module_name,
            format!(
                "failed to write generated file '{}': {error}",
                path.display()
            ),
        )
    })?;
    Ok(true)
}

fn validate_device_folder_name(
    folder_name: &str,
    module_name: &str,
) -> Result<(), RustBackendError> {
    let path = Path::new(folder_name);
    let mut components = path.components();
    match (components.next(), components.next()) {
        (Some(Component::Normal(_)), None) => Ok(()),
        _ => Err(unsafe_device_folder_error(module_name, path)),
    }
}

fn cleanup_stale_generated_rust_files(
    device_dir: &Path,
    expected_files: &HashSet<PathBuf>,
    module_name: &str,
) -> Result<(), RustBackendError> {
    cleanup_stale_generated_rust_files_in(device_dir, device_dir, expected_files, module_name)
}

fn cleanup_stale_generated_rust_files_in(
    device_dir: &Path,
    directory: &Path,
    expected_files: &HashSet<PathBuf>,
    module_name: &str,
) -> Result<(), RustBackendError> {
    let entries = std::fs::read_dir(directory).map_err(|error| {
        RustBackendError::internal(
            "<generated>",
            module_name,
            format!(
                "failed to inspect generated device directory '{}': {error}",
                directory.display()
            ),
        )
    })?;

    for entry in entries {
        let entry = entry.map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                module_name,
                format!(
                    "failed to inspect generated device directory '{}': {error}",
                    directory.display()
                ),
            )
        })?;
        let path = entry.path();
        let file_type = entry.file_type().map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                module_name,
                format!(
                    "failed to inspect generated path '{}': {error}",
                    path.display()
                ),
            )
        })?;

        if file_type.is_dir() {
            cleanup_stale_generated_rust_files_in(&device_dir, &path, expected_files, module_name)?;
            remove_empty_generated_directory(&path, module_name)?;
            continue;
        }

        if !file_type.is_file()
            || path.extension().and_then(|extension| extension.to_str()) != Some("rs")
        {
            continue;
        }

        let relative = path.strip_prefix(device_dir).map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                module_name,
                format!(
                    "failed to classify generated file '{}': {error}",
                    path.display()
                ),
            )
        })?;
        if expected_files.contains(relative) {
            continue;
        }

        std::fs::remove_file(&path).map_err(|error| {
            RustBackendError::internal(
                "<generated>",
                module_name,
                format!(
                    "failed to remove stale generated file '{}': {error}",
                    path.display()
                ),
            )
        })?;
    }

    Ok(())
}

fn remove_empty_generated_directory(
    directory: &Path,
    module_name: &str,
) -> Result<(), RustBackendError> {
    match std::fs::remove_dir(directory) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::DirectoryNotEmpty => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(RustBackendError::internal(
            "<generated>",
            module_name,
            format!(
                "failed to remove empty generated directory '{}': {error}",
                directory.display()
            ),
        )),
    }
}

fn validate_relative_path(path: &str, module_name: &str) -> Result<(), RustBackendError> {
    let path = Path::new(path);
    if path.is_absolute() {
        return Err(unsafe_path_error(module_name, path));
    }

    let mut has_component = false;
    for component in path.components() {
        match component {
            Component::Normal(_) => {
                has_component = true;
            }
            _ => return Err(unsafe_path_error(module_name, path)),
        }
    }
    if !has_component {
        return Err(unsafe_path_error(module_name, path));
    }

    Ok(())
}

fn case_folded_relative_path(path: &Path) -> String {
    let mut key = String::new();
    for component in path.components() {
        if let Component::Normal(part) = component {
            if !key.is_empty() {
                key.push('/');
            }
            key.push_str(&part.to_string_lossy().to_ascii_lowercase());
        }
    }
    key
}

fn unsafe_path_error(module_name: &str, path: &Path) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        module_name,
        format!("unsafe generated relative path '{}'", path.display()),
    )
}

fn unsafe_device_folder_error(module_name: &str, path: &Path) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        module_name,
        format!("unsafe generated device folder '{}'", path.display()),
    )
}

fn duplicate_relative_path_error(module_name: &str, path: &str) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        module_name,
        format!("duplicate generated relative path '{path}'"),
    )
}

fn case_colliding_relative_path_error(module_name: &str, path: &str) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        module_name,
        format!("case-colliding generated relative path '{path}'"),
    )
}

fn duplicate_device_folder_error(path: &str) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        "<devices>",
        format!("duplicate generated device folder '{path}'"),
    )
}

fn case_colliding_device_folder_error(path: &str) -> RustBackendError {
    RustBackendError::internal(
        "<generated>",
        "<devices>",
        format!("case-colliding generated device folder '{path}'"),
    )
}
